import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String bits = sc.next();
    long value = 0;
    for (char bit : bits.toCharArray()) value = value * 2 + (bit - '0');
    System.out.println(value);
  }
}

