import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int k = sc.nextInt();
    String word = sc.next();
    StringBuilder out = new StringBuilder();
    for (char ch : word.toCharArray()) out.append((char) ('A' + (ch - 'A' + k) % 26));
    System.out.println(out);
  }
}

